package com.example.bodega.inventario.controller;
import com.example.bodega.inventario.dto.*; import com.example.bodega.inventario.enums.TipoMovimiento; import com.example.bodega.inventario.service.InventarioService; import com.example.bodega.security.SecurityUser;
import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/inventario") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')")
public class InventarioController { private final InventarioService service; @GetMapping("/movimientos") public Page<MovimientoResponse> listar(@RequestParam(required=false) Long productoId,@RequestParam(required=false) TipoMovimiento tipo,@RequestParam(required=false) LocalDate desde,@RequestParam(required=false) LocalDate hasta,@PageableDefault(size=30,sort="fecha",direction=Sort.Direction.DESC) Pageable pageable){return service.listar(productoId,tipo,desde,hasta,pageable);} @PostMapping("/movimientos") public ResponseEntity<MovimientoResponse> registrar(@Valid @RequestBody MovimientoRequest r,@AuthenticationPrincipal SecurityUser user){return ResponseEntity.status(HttpStatus.CREATED).body(service.registrar(r,user.id()));} }
